package com.financecoach.controller;
import com.financecoach.dto.*;import com.financecoach.entity.TransactionType;import com.financecoach.security.UserPrincipal;import com.financecoach.service.TransactionService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api/transactions") public class TransactionController {private final TransactionService service;public TransactionController(TransactionService service){this.service=service;}@GetMapping public ResponseEntity<List<TransactionDto>> list(@AuthenticationPrincipal UserPrincipal p,@RequestParam(required=false)String query,@RequestParam(required=false)TransactionType type,@RequestParam(required=false)String category,@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to){return ResponseEntity.ok(service.list(p.getId(),query,type,category,from,to));}@PostMapping public ResponseEntity<TransactionDto> create(@AuthenticationPrincipal UserPrincipal p,@Valid @RequestBody TransactionRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(p.getId(),r));}@PutMapping("/{id}")public ResponseEntity<TransactionDto> update(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long id,@Valid @RequestBody TransactionRequest r){return ResponseEntity.ok(service.update(p.getId(),id,r));}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long id){service.delete(p.getId(),id);return ResponseEntity.noContent().build();}@PostMapping(value="/import",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public ResponseEntity<Map<String,Integer>> importFile(@AuthenticationPrincipal UserPrincipal p,@RequestPart("file")MultipartFile file){return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("imported",service.importCsv(p.getId(),file)));}}
